parameters.jsCode:
const items = $input.all();

for (const item of items) {
  const body = item.json.body || {};
  const error = body.error || '';

  // Strip ANSI escape codes
  const cleanError = error
    .replace(/\x1B\[[0-9;]*[a-zA-Z]/g, '')
    .replace(/�\[\d+m/g, '')
    .replace(/\u001b\[[0-9;]*m/g, '');

  // Clean up browsers format: remove brackets
  const rawBrowsers = (body.browsers || '').trim();
  const cleanBrowsers = rawBrowsers.replace(/\[|\]/g, '').replace(/,/g, ', ');

  // Extract summary from the error output if webhook summary is empty
  const rawSummary = (body.summary || '').trim();
  let summary = rawSummary;
  if (!summary) {
    const failedMatch = cleanError.match(/(\d+)\s+failed/);
    const passedMatch = cleanError.match(/(\d+)\s+passed/);
    const parts = [];
    if (failedMatch) parts.push(failedMatch[0]);
    if (passedMatch) parts.push(passedMatch[0]);
    if (parts.length > 0) summary = parts.join(', ');
  }

  // Extract specific test name from error output
  let specificTest = body.testName || 'Unknown test';
  const nameMatch = cleanError.match(/\.spec\.ts:\d+:\d+\s+›\s+(.+)/);
  if (nameMatch) {
    specificTest = nameMatch[1].trim();
  }

  item.json.cleanError = cleanError;
  item.json.testName = specificTest;
  item.json.failedTests = (body.failedTests || '').replace(/\\n/g, '\n').trim();
  item.json.browsers = cleanBrowsers;
  item.json.summary = summary;
  item.json.branch = body.branch || 'unknown';
  item.json.commit = body.commit || 'unknown';
  item.json.repo = body.repo || 'chargeback-qa-suite';
  item.json.owner = body.owner || 'ptrcja';
  item.json.runUrl = body.runUrl || '';
  item.json.nodeVersion = body.nodeVersion || '';
  item.json.os = body.os || '';

  // Build commit URL
  item.json.commitUrl = `https://github.com/${item.json.owner}/${item.json.repo}/commit/${item.json.commit}`;
}

return items;
